(bool status, ) = msg.sender.call.value(to_send)("");
require(status, "transfer eth failed");

TokenInterfaceERC20(ef_token).destroyTokens(msg.sender, _amount);
emit CFFWithdraw(msg.sender, to_send, _amount, getVirtualPrice());
