uint256 x = st.safeMul(mlr).safeSub(e.safeMul(10000)).safeDiv(uint256(10000).safeSub(mlr));
uint256 y = st.safeMul(lt).safeDiv(10000).safeSub(e).safeSub(1);
if (x > y) {x = y;}
